def ev_id(name="event_id", null=False, defn="Event key '<game_id>:<source>:<seq>' (FK events)."):
    return C(name, "string", None, "'<game_id>:<source>:<int>'", null, defn, {"O": "events"}, ["R-EV-01", "R-EV-12"])

